import test from 'node:test';
import assert from 'node:assert/strict';
import { existsSync } from 'node:fs';
import { join } from 'node:path';
import { OUT, staleFiles } from '../../scripts/assets-catalog';
import { buildManifest } from '../../scripts/assets/manifest';

// docs/assets is generated by `npm run assets:catalog` (never edited by hand): it must match the registries and public/pixel.
test('docs/assets is up to date', () => {
	const stale = staleFiles();
	assert.deepEqual(stale, [], `stale: ${stale.join(', ')}; run \`npm run assets:catalog\``);
});

test('asset names are unique and every picture exists', () => {
	const m = buildManifest();
	assert.equal(new Set(m.map((e) => e.name)).size, m.length);
	for (const e of m) assert.ok(existsSync(join(OUT, '..', '..', 'public', e.src)), `${e.name}: missing ${e.src}`);
});
